namespace sv_4dc61b7739c44e2f89e1a4c06fc0cb52.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service holding the current warehouse selection for a single circuit.
/// Every interactive component in the circuit shares this instance.
/// </summary>
public class WarehouseState
{
    private string _currentWarehouseId = "WH1";

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "WH1", Name = "Warehouse A — Main Distribution" },
        new() { Id = "WH2", Name = "Warehouse B — West Coast" },
        new() { Id = "WH3", Name = "Warehouse C — East Coast" },
    ];

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_4dc61b7739c44e2f89e1a4c06fc0cb52.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the current warehouse.
/// Polling is controlled externally (start/stop); when new data arrives
/// every subscriber is notified via OnAlertCountChanged.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _pollingConsumers;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired whenever the alert count changes.  Subscribers MUST wrap
    /// StateHasChanged in InvokeAsync because this fires from a timer thread.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>Simulates a database query — returns a random number 0-15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begin polling every 10 seconds.  Multiple consumers can call this;
    /// only the first starts the timer.
    /// </summary>
    public void StartPolling()
    {
        _pollingConsumers++;
        if (_pollingConsumers > 1)
            return;

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(_cts.Token);
    }

    /// <summary>
    /// Stop polling.  Only the last consumer actually stops the timer.
    /// </summary>
    public void StopPolling()
    {
        _pollingConsumers = Math.Max(0, _pollingConsumers - 1);
        if (_pollingConsumers > 0)
            return;

        CancelTimer();
    }

    /// <summary>
    /// Immediately refresh the alert count and notify all subscribers.
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch once immediately so the UI isn't blank until the first tick.
        await RefreshAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on disposal / stop.
        }
    }

    private async void OnWarehouseChanged()
    {
        if (_pollingConsumers > 0)
        {
            await RefreshAsync();
        }
    }

    private void CancelTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        CancelTimer();
    }
}

