@page "/dashboard"
@rendermode InteractiveServer
@inject sv_4dc61b7739c44e2f89e1a4c06fc0cb52.Services.WarehouseState WarehouseState
@inject sv_4dc61b7739c44e2f89e1a4c06fc0cb52.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-5">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            @if (AlertService.CurrentAlertCount > 0)
            {
                <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentAlertCount</span>
            }
            else
            {
                <span class="badge bg-success rounded-pill ms-2">0</span>
            }
        </h5>
        <p class="card-text text-muted">
            Checking for items below minimum inventory levels every 10 seconds.
        </p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes (fires from timer — use InvokeAsync).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Subscribe to warehouse changes (fires from Blazor sync context).
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling while this page is visible.
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

